def gen(rng):
    def fmt(vals):
        return str(len(vals)) + '\n' + ' '.join(map(str, vals))
    tests = [fmt([5]), fmt([2, 1]), fmt([1, 2]), fmt([3, 3, 3]), fmt([4, 2, 9, -3, 2, 7]), fmt([1, 2, 3, 4]), fmt([10**9, -10**9]), fmt([5, 4, 3, 2, 1])]
    for n in (2, 3, 4, 5, 7, 10, 15, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(-10, 10) for _ in range(n)]))
    N = 50000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt([rng.randint(-3, 3) for _ in range(N)]))
    tests.append(fmt(sorted(rng.randint(-10**9, 10**9) for _ in range(N))))
    return tests
